WITH a AS (
  SELECT count(*) AS n_idt_ranked FROM "2024_CSN_Metropolitan_Areas_Identity_Theft_Reports" WHERE TRY_CAST("Rank" AS INT) IS NOT NULL
), b AS (
  SELECT count(*) AS n_fraud_ranked FROM "2024_CSN_Metropolitan_Areas_Fraud_and_Other_Reports" WHERE TRY_CAST("Rank" AS INT) IS NOT NULL
), c AS (
  SELECT count(*) AS n_state_msa_idt FROM State_MSA_Identity_Theft_data WHERE TRY_CAST(column1 AS BIGINT) IS NOT NULL
)
SELECT a.n_idt_ranked, b.n_fraud_ranked, c.n_state_msa_idt FROM a, b, c

